using System;
using System.Collections.Generic;

namespace Risebird.Entities.ViewModel
{
    /// <summary>
    /// This class refers to the latest version of Video Sentiment Analysis generated by AWS Rekognition
    /// </summary>
    public class VideoSentimentAnalysis
    {
        public string CandidateName { get; set; } = string.Empty;
        public string CandidateEmail { get; set; } = string.Empty;
        public DateTime InterviewDate { get; set; } = DateTime.Now;
        public string ResumeLink { get; set; } 
        public string SessionId { get; set; } = string.Empty;
        public int InterviewId { get; set; } = 0;
        public string VideoUrl { get; set; }
        public int id { get; set; }

        public int biqvId { get; set; }

        public float? FEAR { get; set; }

        public float? CONFUSED { get; set; }

        public float? SAD { get; set; }

        public float? CALM { get; set; }

        public float? SURPRISED { get; set; }

        public float? DISGUSTED { get; set; }

        public float? ANGRY { get; set; }

        public float? HAPPY { get; set; }

        public DateTime CreatedAt { get; set; }

        public string CreatedBy { get; set; } = string.Empty;
    }

    /// <summary>
    /// Outcome of a sentiment analysis request, carrying the reason when analysis
    /// could not be produced so the caller can show it instead of a bare failure.
    /// </summary>
    public class SentimentAnalysisResultVM
    {
        public bool Success { get; set; }
        public string Message { get; set; } = string.Empty;
        public VideoSentimentAnalysis Sentiment { get; set; }
    }
}
